/// <summary>
/// Whitelist of allowed item substitutions for the Sales Proration Accelerator.
/// A row says: when FromItemId is short, ToItemId may be offered instead —
/// optionally only for one customer (CustAccount blank = all customers),
/// converted by QtyRatio, within ValidFrom/ValidTo.
/// </summary>
public class RSMItemSubstitution extends common
{
}

Method.Source:
/// <summary>Active rule for an exact (from, to, customer) triple; customer-specific wins over blank.</summary>
public static RSMItemSubstitution findActive(
    ItemId      _fromItemId,
    ItemId      _toItemId,
    CustAccount _custAccount = '',
    TransDate   _asOf        = systemDateGet())
{
    RSMItemSubstitution sub;

    // Customer-specific row first, then the all-customer row.
    if (_custAccount)
    {
        select firstonly sub
            where sub.FromItemId  == _fromItemId
               && sub.ToItemId    == _toItemId
               && sub.CustAccount == _custAccount
               && (!sub.ValidFrom || sub.ValidFrom <= _asOf)
               && (!sub.ValidTo   || sub.ValidTo   >= _asOf);
    }
    if (!sub)
    {
        select firstonly sub
            where sub.FromItemId  == _fromItemId
               && sub.ToItemId    == _toItemId
               && sub.CustAccount == ''
               && (!sub.ValidFrom || sub.ValidFrom <= _asOf)
               && (!sub.ValidTo   || sub.ValidTo   >= _asOf);
    }
    return sub;
}

/// <summary>
/// The rule that lets this customer take _toItemId for _fromItemId, honouring
/// CustTable.RSMSubstitutionPolicy: Never = none; CustomerOnly = only rows
/// naming the customer; Standard = customer row, else all-customer row.
/// Bidirectional rows match in reverse. Mirrors public/js/shared/subs.js in
/// the web app, so the planner only proposes what this method accepts.
/// </summary>
public static RSMItemSubstitution findForCustomer(
    ItemId    _fromItemId,
    ItemId    _toItemId,
    CustTable _cust,
    TransDate _asOf = systemDateGet())
{
    RSMItemSubstitution sub;

    if (_cust.RSMSubstitutionPolicy == RSMSubstitutionPolicy::Never)
    {
        return sub;
    }
    sub = RSMItemSubstitution::findActive(_fromItemId, _toItemId, _cust.AccountNum, _asOf);
    if (!sub)
    {
        RSMItemSubstitution back = RSMItemSubstitution::findActive(_toItemId, _fromItemId, _cust.AccountNum, _asOf);
        if (back.Direction == RSMSubstitutionDirection::Bidirectional)
        {
            sub = back;
        }
    }
    if (sub && !sub.CustAccount && _cust.RSMSubstitutionPolicy == RSMSubstitutionPolicy::CustomerOnly)
    {
        sub = null;
    }
    return sub;
}

/// <summary>Substitute units per ordered unit when substituting away from _orderedItemId (inverse for a reversed bidirectional rule).</summary>
public RSMSubstitutionQtyRatio ratioFrom(ItemId _orderedItemId)
{
    RSMSubstitutionQtyRatio r = this.QtyRatio > 0 ? this.QtyRatio : 1.0;
    return _orderedItemId == this.FromItemId ? r : 1.0 / r;
}

/// <summary>
/// All active substitutes for an item (ranked). Includes Bidirectional rows
/// where the item appears on the To side.
/// </summary>
public static List activeSubstitutesFor(
    ItemId      _itemId,
    CustAccount _custAccount = '',
    TransDate   _asOf        = systemDateGet())
{
    List                result = new List(Types::Record);
    RSMItemSubstitution sub;

    while select sub
        order by sub.Rank asc
        where (sub.FromItemId == _itemId
           || (sub.ToItemId   == _itemId && sub.Direction == RSMSubstitutionDirection::Bidirectional))
           && (sub.CustAccount == _custAccount || sub.CustAccount == '')
           && (!sub.ValidFrom || sub.ValidFrom <= _asOf)
           && (!sub.ValidTo   || sub.ValidTo   >= _asOf)
    {
        result.addEnd(sub);
    }
    return result;
}

public boolean validateWrite()
{
    boolean ok = super();

    if (this.FromItemId == this.ToItemId)
    {
        ok = checkFailed("@SYS9039"); // An item cannot substitute itself.
    }
    if (this.QtyRatio <= 0)
    {
        this.QtyRatio = 1.0;
    }
    if (this.ValidFrom && this.ValidTo && this.ValidFrom > this.ValidTo)
    {
        ok = checkFailed("@SYS72396"); // From date is after To date.
    }
    return ok;
}
